  /* ------------------------------------------------------------------ *
   * Streaming tar parser
   * ------------------------------------------------------------------ */
  const TEXT_EXTENSION = /\.(?:[cm]?js|json|jsx|tsx?|md|txt|map|css|html?|ya?ml|flow|svg|scss|less)$/i;
